        let (t, _) = type_run(&mut pet, t, 3, 4, 50, 0.045);
        assert_eq!(pet.pending_pets(), 0, "the latch expired mid-chase");
        let (_, _f) = idle(&mut pet, t, (3, 54), 0.6);
